{
  "decision": "RESPALDADA",
  "reglas": ["D1"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A01",
      "fragmento": "El archivo Liria abre de martes a sábado, desde las 08:30 hasta las 13:30."
    }
  ],
  "justificacion_breve": "El documento indica que el archivo Liria abre de martes a sábado a las 08:30; el miércoles está dentro de ese rango, por lo que la afirmación es respaldada."
}

{
  "decision": "RESPALDADA",
  "reglas": ["D1"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A02",
      "fragmento": "La consulta del índice digital del archivo Narel no requiere pago."
    },
    {
      "documento": "BANCO-A",
      "seccion": "A02",
      "fragmento": "La reproducción certificada cuesta cuatro unidades por documento. Su tarifa no se aplica a la consulta del índice."
    }
  ],
  "justificacion_breve": "Los pasajes confirman que la consulta del índice digital es gratuita y que la reproducción certificada tiene una tarifa, coincidiendo exactamente con la afirmación."
}

{
  "decision": "CONTRADICHA",
  "reglas": ["D1"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A03",
      "pagina": 0,
      "fragmento": "El contenedor Arven contiene doce piezas."
    }
  ],
  "justificacion_breve": "El pasaje autoritativo indica que el contenedor Arven contiene doce piezas, mientras que la afirmación sostiene que contiene quince; por lo tanto, la afirmación contradice la evidencia documental."
}

{
  "decision": "CONTRADICHA",
  "reglas": ["D1", "D2", "D5"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A04",
      "pagina": 0,
      "fragmento": "La norma Darel acepta duraciones estrictamente superiores a ocho minutos e iguales o inferiores a trece minutos. El registro D4 indica exactamente ocho minutos."
    },
    {
      "documento": "BANCO-A",
      "seccion": "A04",
      "pagina": 1,
      "fragmento": "El expediente D4 satisface los demás requisitos. Ninguno de ellos sustituye el requisito de duración."
    }
  ],
  "justificacion_breve": "La norma Darel exige duración >8 min y ≤13 min; D4 registra exactamente ocho minutos, por lo que no cumple el requisito de duración."
}

{
  "decision": "CONTRADICHA",
  "reglas": ["D1", "D2", "D5"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A05",
      "pagina": 0,
      "fragmento": "La norma Elmar exige dos verificaciones concordantes y un cierre firmado. El expediente E5 dispone de ambas verificaciones y de cierre firmado."
    },
    {
      "documento": "BANCO-A",
      "seccion": "A05",
      "pagina": 1,
      "fragmento": "Una suspensión activa impide emitir el acta conforme aunque se satisfagan los demás requisitos. E5 mantiene una suspensión activa."
    }
  ],
  "justificacion_breve": "Aunque E5 cumple con verificaciones y cierre firmado, la presencia de una suspensión activa impide emitir el acta conforme, contradiciendo la afirmación."
}

{
  "decision": "EVIDENCIA_INSUFICIENTE",
  "reglas": ["D3"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A06",
      "fragmento": "En el lote Faril se analizaron diez muestras adultas. Siete conservaron la señal durante dos días."
    },
    {
      "documento": "BANCO-A",
      "seccion": "A06",
      "fragmento": "El informe no incluye muestras juveniles ni observaciones posteriores al segundo día."
    }
  ],
  "justificacion_breve": "Los pasajes sólo describen datos de muestras adultas (señal de dos días) y expresan explícitamente que no se incluyen muestras juveniles ni observaciones más allá del segundo día; por lo tanto, la afirmación sobre la duración de la señal en muestras juveniles durante una semana carece de respaldo documental."
}

{
  "decision": "RESPALDADA",
  "reglas": ["D1", "D4"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A07",
      "pagina": 0,
      "fragmento": "La ficha Garel prescribe conservar el archivo durante seis meses."
    },
    {
      "documento": "BANCO-A",
      "seccion": "A07",
      "pagina": 1,
      "fragmento": "La anotación del tercero no cambia la prescripción documental de seis meses."
    }
  ],
  "justificacion_breve": "Los pasajes del documento BANCO-A/A07 afirman explícitamente que la ficha Garel prescribe conservar el archivo durante seis meses y que la anotación de un tercero no altera dicha prescripción; por lo tanto la afirmación está respaldada."
}

{
  "decision": "CONTRADICHA",
  "reglas": ["D1", "D2", "D4"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A08",
      "pagina": 0,
      "fragmento": "El registro Horel uno declara autorizado el acceso nocturno de H8. El registro Horel dos declara no autorizado ese mismo acceso para H8, en la misma fecha y recinto."
    },
    {
      "documento": "BANCO-A",
      "seccion": "A08",
      "pagina": 1,
      "fragmento": "Ambos registros están vigentes. No se aporta anulación, jerarquía ni regla que conceda precedencia a uno de ellos."
    }
  ],
  "justificacion_breve": "Los documentos presentan dos registros contradictorios: uno autoriza y otro niega el acceso nocturno de H8, sin indicarse jerarquía que resuelva la discrepancia, por lo que no se puede concluir que H8 tenga autorizado dicho acceso."
}

{
  "decision": "CONTRADICHA",
  "reglas": ["D1", "D2", "D5"],
  "evidencias": [
    {
      "documento": "BANCO-A",
      "seccion": "A09",
      "pagina": 0,
      "fragmento": "En el estudio observacional Ivara, las estaciones con marca azul tuvieron menos registros discordantes."
    },
    {
      "documento": "BANCO-A",
      "seccion": "A09",
      "pagina": 1,
      "fragmento": "El informe establece que estos datos no permiten concluir una relación causal ni extender el resultado a todas las estaciones."
    }
  ],
  "justificacion_breve": "La afirmación atribuye a Ivara una demostración causal y universal de que la marca azul reduce discordancias, mientras que la fuente indica solo una observación correlacional y advierte que no se puede inferir causalidad ni generalizar a todas las estaciones, contradiciendo la afirmación."
}
